"""Spine vectors: Python must reproduce the JS-generated bytes exactly."""

import hashlib
import unittest
from datetime import datetime, timezone

from diligenceos.flashy import seller, witness
from diligenceos.flashy.spine import CanonError, SpineKey, canonical, hash_of, sha256hex, verify_doc

from .helpers import HERE, VECTORS, node_json

PINNED_VECTORS_SHA256 = "72ebc9d5ef9f7a60e1109c8e22d962030eb23f3a055143474f37ef9f73cf197b"
V = VECTORS


def utc(s):
    return datetime.fromisoformat(s)


class VectorFileTest(unittest.TestCase):
    def test_vectors_file_is_the_pinned_copy(self):
        got = hashlib.sha256((HERE / "fixtures" / "vectors.json").read_bytes()).hexdigest()
        self.assertEqual(got, PINNED_VECTORS_SHA256, "vectors.json changed: re-copy deliberately and re-pin")


class CanonicalVectorsTest(unittest.TestCase):
    def test_canonical_cases_byte_for_byte(self):
        for c in V["canonical"]:
            self.assertEqual(canonical(c["input"]), c["canonical"], c["name"])
            self.assertEqual(sha256hex(canonical(c["input"])), c["sha256"], c["name"])

    def test_refuses_floats_nan_and_unsupported(self):
        for bad in ({"a": 1.5}, {"a": float("nan")}, {"a": 1.0}, {"a": 2**53}, {"a": {1, 2}}, {"a": b"x"},
                    {1: "a"}, {"a": "\ud800"}, [object()]):
            with self.assertRaises(CanonError, msg=repr(bad)):
                canonical(bad)

    def test_bool_is_not_an_integer(self):
        self.assertEqual(canonical({"a": True, "b": False}), '{"a":true,"b":false}')

    def test_key_order_matches_javascript_beyond_the_bmp(self):
        # JS sorts by UTF-16 code unit: U+FF5E (BMP) sorts AFTER U+1F600 (surrogate pair D83D...).
        self.assertEqual(canonical({"～": 1, "\U0001f600": 2}), '{"\U0001f600":2,"～":1}')


class SignatureVectorTest(unittest.TestCase):
    def test_seed_to_pub_and_signature_reproduced(self):
        s = V["signature"]
        k = SpineKey.from_seed_hex(s["seedHex"])
        self.assertEqual(k.pub_hex, s["publicKeyHex"])
        self.assertEqual(k.sign(s["domain"], s["doc"]), s["signatureHex"])

    def test_domain_key_doc_and_garbage_refusals(self):
        s = V["signature"]
        ok = lambda **kw: verify_doc(kw.get("pub", s["publicKeyHex"]), kw.get("domain", s["domain"]),
                                     kw.get("doc", s["doc"]), kw.get("sig", s["signatureHex"]))
        self.assertTrue(ok())
        self.assertFalse(ok(domain="other/domain/1"))
        self.assertFalse(ok(doc={"x": "2", "y": ["a"]}))
        self.assertFalse(ok(pub=SpineKey.from_seed_hex("22" * 32).pub_hex))
        for bad in (None, "zz", "0" * 128, s["signatureHex"].upper(), s["signatureHex"][:-2]):
            self.assertFalse(ok(sig=bad), repr(bad))
        self.assertFalse(ok(doc={"x": 1.5}))
        self.assertFalse(ok(pub="not hex"))

    def test_bad_seed_refused(self):
        for bad in ("", "aa", "zz" * 32, None, "A1" * 32):
            with self.assertRaises(ValueError):
                SpineKey.from_seed_hex(bad)


class InvoiceVectorTest(unittest.TestCase):
    def setUp(self):
        self.iv = V["invoice"]
        self.now = utc(self.iv["verifyAt"])
        self.pub = self.iv["sellerPublicKeyHex"]

    def test_vector_invoice_verifies_against_pinned_key(self):
        self.assertTrue(seller.verify_invoice(self.iv["invoice"], self.pub, self.now))

    def test_make_invoice_reproduces_vector_exactly(self):
        i = self.iv["invoice"]
        mine = seller.make_invoice(SpineKey.from_seed_hex("a1" * 32), invoice_id=i["invoiceId"], seller=i["seller"],
                                   payee=i["payee"], chain=i["chain"], asset=i["asset"], amount=i["amount"],
                                   deliverable="bytes", expires_at=i["expiresAt"])
        self.assertEqual(mine, i)
        self.assertEqual(hash_of({"d": "bytes"}), i["deliverableHash"])

    def test_refusals(self):
        i = self.iv["invoice"]
        t = self.now
        cases = {
            "unpinned (other key)": (i, SpineKey.from_seed_hex("33" * 32).pub_hex, t),
            "no pin": (i, None, t),
            "expired": (i, self.pub, utc("2026-10-14T12:00:00+00:00")),
            "expired later": (i, self.pub, utc("2026-10-15T00:00:00+00:00")),
            "tampered amount": ({**i, "amount": "1"}, self.pub, t),
            "tampered payee": ({**i, "payee": "0x" + "11" * 20}, self.pub, t),
            "extra field": ({**i, "note": "x"}, self.pub, t),
            "missing field": ({k: v for k, v in i.items() if k != "seller"}, self.pub, t),
            "float amount": ({**i, "amount": 1.5}, self.pub, t),
            "int amount": ({**i, "amount": 1500000}, self.pub, t),
            "non-canonical amount": ({**i, "amount": "01500000"}, self.pub, t),
            "decimal amount": ({**i, "amount": "1.5"}, self.pub, t),
            "negative amount": ({**i, "amount": "-5"}, self.pub, t),
            "zero amount": ({**i, "amount": "0"}, self.pub, t),
            "bad sig": ({**i, "sig": "00" * 64}, self.pub, t),
            "no sig": ({k: v for k, v in i.items() if k != "sig"}, self.pub, t),
            "key carried inside differs from pin": ({**i, "sellerKey": SpineKey.from_seed_hex("33" * 32).pub_hex}, self.pub, t),
            "not a dict": ("x", self.pub, t),
            "unknown chain": ({**i, "chain": "evm:1"}, self.pub, t),
            "bad expiry format": ({**i, "expiresAt": "tomorrow"}, self.pub, t),
        }
        for name, (inv, pub, now) in cases.items():
            self.assertFalse(seller.verify_invoice(inv, pub, now), name)

    def test_make_invoice_refuses_bad_inputs(self):
        k = SpineKey.from_seed_hex("a1" * 32)
        base = dict(invoice_id="i", seller="s", payee="0x" + "11" * 20, chain="evm:31337", asset="0x" + "ab" * 20,
                    amount="5", deliverable="d", expires_at="2026-10-14T12:00:00.000Z")
        for over in ({"chain": "evm:1"}, {"amount": "0"}, {"amount": "1.5"}, {"amount": 5}, {"expires_at": "soon"},
                     {"payee": "0x12"}, {"deliverable": {"not": "a string"}}):
            with self.assertRaises((ValueError, TypeError), msg=str(over)):
                seller.make_invoice(k, **{**base, **over})


class LogVectorTest(unittest.TestCase):
    def test_vector_log_verifies(self):
        r = witness.verify_plane_log(V["log"]["entries"], V["log"]["publicKeyHex"])
        self.assertTrue(r["ok"])
        self.assertEqual(r["count"], 2)
        self.assertEqual(r["head"], V["log"]["entries"][-1]["hash"])

    def test_python_rebuilt_log_matches_vector_bytes(self):
        from .helpers import make_log, seed
        e = V["log"]["entries"]
        mine = make_log(SpineKey.from_seed_hex(seed("c3")), [(x["kind"], x["data"]) for x in e], ts=e[0]["ts"])
        self.assertEqual(mine, e)


class SettlementVectorTest(unittest.TestCase):
    def test_vector_rpc_fixture_settles_and_receipt_verifies(self):
        s = V["settlement"]["rpc"]
        replies = {"eth_chainId": s["chainId"], "eth_blockNumber": s["blockNumber"]}

        def rpc(method, params):
            return s["receipt"] if method == "eth_getTransactionReceipt" else replies[method]

        key = SpineKey.from_seed_hex("a1" * 32)
        with self.subTest("ok"):
            import tempfile
            with tempfile.TemporaryDirectory() as d:
                res = seller.settle_invoice(
                    rpc=rpc, seller_key=key, invoice=V["invoice"]["invoice"], tx_hash=s["txHash"], min_confirmations=2,
                    spent=seller.SpentSet(d + "/spent.json"), deliverable="bytes", now=utc(V["invoice"]["verifyAt"]))
            self.assertTrue(res["ok"], res)
            self.assertEqual(res["receipt"]["payer"], s["payer"])
            self.assertEqual(res["receipt"]["finality"], "simulated")
            self.assertEqual(res["receipt"]["releasedAt"], "2026-10-14T09:00:00.000Z")
            self.assertTrue(seller.verify_receipt(res["receipt"], key.pub_hex))
        with self.subTest("needs 3 confirmations, vector has 2"):
            with tempfile.TemporaryDirectory() as d:
                res = seller.settle_invoice(
                    rpc=rpc, seller_key=key, invoice=V["invoice"]["invoice"], tx_hash=s["txHash"], min_confirmations=3,
                    spent=seller.SpentSet(d + "/spent.json"), deliverable="bytes", now=utc(V["invoice"]["verifyAt"]))
            self.assertEqual(res["code"], "NOT_CONFIRMED")


if __name__ == "__main__":
    unittest.main()
